/**
 * This test case verifies CBRD-27245: Improve lexer input handling for UTF-8 statements
 *
 * 1-3  - no padding (control): parses correctly nowhere near a boundary
 * 4-6  - padding exactly on the first refill boundary (offset 8192)
 * 7-9  - padding exactly on the nominal buffer size (offset 16384); not an
 *        actual second refill point for this function, kept as an
 *        equivalence check at the developer's own candidate offset
 * 10   - semicolon inside a literal followed by a second statement same line
 * 11-12 - the UTF-8 character from cbrd_27245_utf8fix.sql, in a literal and as
 *         an alias, straddling the first refill boundary (offset 8192)
 */

SET SYSTEM PARAMETERS 'no_backslash_escapes=no';

evaluate 'Case 1: pad=0 bytes, escaped quote pair (\') control, no padding';
SELECT 'a\'b', 'END_QUOTE' FROM db_root;

evaluate 'Case 2: pad=0 bytes, escaped backslash pair (\\) control, no padding';
SELECT 'a\\', 'END_BACKSLASH' FROM db_root;

evaluate 'Case 3: pad=0 bytes, backslash-n escape (\\n) control, no padding';
SELECT '\n', 'END_NEWLINE' FROM db_root;

evaluate 'Case 4: pad=8183 bytes, escaped quote pair (\') exactly on the first refill boundary (byte offset 8192), splitting the pair';
SELECT '\'b' AS case4, 'END_QUOTE' FROM db_root;

evaluate 'Case 5: pad=8183 bytes, escaped backslash pair (\\) exactly on the first refill boundary (byte offset 8192), splitting the pair, closing quote right after';
SELECT '\\' AS case5, 'END_BACKSLASH' FROM db_root;

evaluate 'Case 6: pad=8183 bytes, backslash-n escape (\\n) exactly on the first refill boundary (byte offset 8192), splitting the pair';
SELECT '\n' AS case6, 'END_NEWLINE' FROM db_root;

evaluate 'Case 7: pad=16375 bytes, escaped quote pair (\') exactly on the nominal buffer-size offset (byte offset 16384), splitting the pair';
SELECT '\'b' AS case7, 'END_QUOTE' FROM db_root;

evaluate 'Case 8: pad=16375 bytes, escaped backslash pair (\\) exactly on the nominal buffer-size offset (byte offset 16384), splitting the pair, closing quote right after';
SELECT '\\' AS case8, 'END_BACKSLASH' FROM db_root;

evaluate 'Case 9: pad=16375 bytes, backslash-n escape (\\n) exactly on the nominal buffer-size offset (byte offset 16384), splitting the pair';
SELECT '\n' AS case9, 'END_NEWLINE' FROM db_root;

evaluate 'Case 10: semicolon inside a string literal immediately followed by a second statement on the same line';
SELECT 'boundary;semicolon' FROM db_root; SELECT 2 FROM db_root;

evaluate 'Case 11: a multi-byte UTF-8 character (U+21861) inside a string literal, straddling the first refill boundary (byte offset 8192)';
SELECT '𡡡' AS case11, 'END4' FROM db_root;

evaluate 'Case 12: the same character used as an alias (outside any literal), straddling the first refill boundary (byte offset 8192)';
SELECT '' AS case12, 1 AS t𡡡 FROM db_root;
SET SYSTEM PARAMETERS 'no_backslash_escapes=yes';
